using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using PITF.Api.Data;using PITF.Api.Models;
namespace PITF.Api.Controllers;
[ApiController,Route("api/admin"),Authorize(Policy="ContentWrite")]public sealed class AdminContentController(ApplicationDbContext db):ControllerBase{
[HttpGet("editions")]public async Task<object>Editions(CancellationToken ct)=>await db.Editions.AsNoTracking().OrderBy(x=>x.Order).ToListAsync(ct);[HttpPost("editions")]public async Task<IActionResult>CreateEdition(Edition x,CancellationToken ct){db.Add(x);await db.SaveChangesAsync(ct);return Created($"api/admin/editions/{x.Id}",x);}[HttpPut("editions/{id:guid}")]public async Task<IActionResult>Edition(Guid id,Edition x,CancellationToken ct){if(id!=x.Id)return BadRequest();db.Update(x);await db.SaveChangesAsync(ct);return NoContent();}
[HttpGet("news")]public async Task<object>News(CancellationToken ct)=>await db.News.AsNoTracking().OrderByDescending(x=>x.Date).ToListAsync(ct);[HttpPost("news")]public async Task<IActionResult>CreateNews(News x,CancellationToken ct){db.Add(x);await db.SaveChangesAsync(ct);return Created($"api/admin/news/{x.Id}",x);}[HttpPut("news/{id:guid}")]public async Task<IActionResult>News(Guid id,News x,CancellationToken ct){if(id!=x.Id)return BadRequest();db.Update(x);await db.SaveChangesAsync(ct);return NoContent();}
[HttpGet("folders")]public async Task<object>Folders(CancellationToken ct)=>await db.MediaFolders.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(ct);[HttpPost("folders")]public async Task<IActionResult>Folder(MediaFolder x,CancellationToken ct){db.Add(x);await db.SaveChangesAsync(ct);return Created($"api/admin/folders/{x.Id}",x);}
[HttpGet("homepage")]public async Task<object>Homepage(CancellationToken ct)=>await db.HomepageSections.AsNoTracking().Include(x=>x.Selections).OrderBy(x=>x.Order).ToListAsync(ct);[HttpPut("homepage/{id:guid}")]public async Task<IActionResult>Homepage(Guid id,HomepageSection x,CancellationToken ct){if(id!=x.Id)return BadRequest();db.Update(x);await db.SaveChangesAsync(ct);return NoContent();}
}
